local a="https://phoenix.madefor.cc/packages/"local b=require"system.filesystem"local c=require"system.network"local d=require"system.process"local e=require"dpkg.control"local f=require"dpkg.query"if d.getuser()~="root"then error("This program must be run as root.")end;print("Checking for updates...")local g,h=c.get(a.."Packages")if not g then error("Could not download package list: "..h)elseif g:responseCode()~=200 then local i=g:responseCode()g:close()error("Could not download package list: HTTP "..i)end;local j=e.parseControlList(g:read("*a"))g:close()local k={}for l,m in ipairs(j)do k[m.Package]=m end;local n=f.readDatabase()local o={}for p,m in pairs(n)do if not m.Status:match"^deinstall "and k[p]and k[p].Version~=m.Version then o[#o+1]=p end end;if#o==0 then print("No updates available.")return true end;table.sort(o,function(q,r)if q=="dpkg"then return true elseif r=="dpkg"then return false else return q<r end end)print("The following package updates are available:")for l,m in ipairs(o)do print("  "..m..": "..n[m].Version.." -> "..k[m].Version)end;io.write("Install these updates? (y/N) ")local s=io.read()if not s or s:lower()~="y"then return false end;b.mkdir("/tmp/pkgcache")b.mount("tmpfs","tmpfs","/tmp/pkgcache",{})for l,m in ipairs(o)do print("Downloading "..m.." ("..math.floor(k[m].Size/1024).." kiB)")g,h=c.get{url=a..m..".deb",encoding="binary"}if not g then b.unmount("/tmp/pkgcache")error("Failed to download package: "..h)elseif g:responseCode()~=200 then b.unmount("/tmp/pkgcache")local i=g:responseCode()g:close()error("Failed to download package: HTTP "..i)end;local t,h=b.open("/tmp/pkgcache/"..m..".deb","wb")if not t then g:close()b.unmount("/tmp/pkgcache")error("Failed to write package: "..h)end;t.write(g:read("*a"))t.close()g:close()end;local u=true;for l,m in ipairs(o)do u=d.run("/usr/bin/dpkg","-i","/tmp/pkgcache/"..m..".deb")and u end;b.unmount("/tmp/pkgcache")print("Update complete. It may be necessary to reboot your computer to use the new software.")return u
